function pf(k,l,o){o=o||{};const r=prRec();const v=gp(r,k)??'';const id='p_'+k.replace(/\W/g,'_');const er=PR.errs[k];const dis=o.ro||r.cerrado;
 const a=`id="${id}" ${er?`aria-invalid="true" aria-describedby="e${id}"`:''} ${dis?'disabled':''} onchange="pset('${k}',this.${o.t=='check'?'checked?1:0':'value'}${o.rr?',1':''})"${o.live?` oninput="pset('${k}',this.value);${o.live}"`:''}`;let h;
 if(o.t=='check')return `<label class="ckr ${er?'bad':''}"><input type="checkbox" ${a} ${v?'checked':''}><span>${l}</span></label>${er?`<div class="fe" id="e${id}" role="alert">${I('warn')}${esc(er)}</div>`:''}`;
 if(o.t=='sel')h=`<select ${a}><option value="">Elija…</option>${(typeof o.o=='function'?o.o():o.o).map(x=>`<option ${x==v?'selected':''}>${esc(x)}</option>`).join('')}</select>`;
 else if(o.t=='area')h=`<textarea ${a}>${esc(v)}</textarea>`;
 else h=`<input ${a} value="${esc(v)}" ${o.t=='date'?'placeholder="dd/mm/aaaa" inputmode="numeric"':o.t=='num'?'inputmode="numeric"':''} autocomplete="off">`;
 return `<div class="fld ${o.w?'w2':''}"><label class="fl" for="${id}">${l}${o.req?' <span class="req">(obligatorio)</span>':''}</label>${h}${o.help?`<div class="fh">${o.help}</div>`:''}${er?`<div class="fe" id="e${id}" role="alert">${I('warn')}${esc(er)}</div>`:''}</div>`}
