const venc=e=>e&&/^\d\d\/\d\d\/\d{4}$/.test(e)&&daysBetween(e,HOY)>182;
function matDocs(r){let t=0,o=0;CT.forEach(([c])=>DOCS.forEach(([k])=>{const v=gp(r,`docs.${c}.${k}.est`)||'Pendiente';if(v!='No aplica'){t++;if(v=='Recibido')o++}}));return [o,t||1]}
function waPend(){const r=prRec();const L=[];CT.forEach(([c,l])=>DOCS.forEach(([k,n])=>{const v=gp(r,`docs.${c}.${k}.est`)||'Pendiente';if(v=='Pendiente'||v=='Observado')L.push(`• ${l}: ${n}${v=='Observado'?' (observado)':''}`)}));
 ask({t:'Enviar pendientes por WhatsApp',txt:'Vista previa del mensaje a los novios',html:`<div class="phone"><div class="bub">Hola, ${esc((r.novio.n||'').split(' ')[0])} y ${esc((r.novia.n||'').split(' ')[0])}. Para su expediente ${r.num} aún falta:<br>${L.map(esc).join('<br>')||'Nada, ¡todo completo!'}<br>Pueden traerlos de lunes a viernes de 9:00 a 13:00. Parroquia San José.</div></div>`,ok:'Enviar',undo:false,onok:()=>commit('Lista de pendientes enviada por WhatsApp (simulado)',()=>hist(r,'Envió pendientes por WhatsApp'),{acc:'Envió aviso',ent:'Sacramentos',obj:r.num},{keep:1})})}
const dsp=r=>DB.aprob.find(a=>a.id==r.esp.aprob);
function hojaMat(){const r=prRec();hojaTranscribir('Matrimonio '+r.num,[['Novio',r.novio.n],['Novia',r.novia.n],['Fecha',r.prog.fecha],['Ministro',r.cel.ministro],['Testigos',r.testigos.map(t=>t.n).join(' · ')]])}
function cobrarMat(){const r=prRec();const ar=DB.aranceles.find(a=>/Matrimonio/.test(a.concepto));const id=r.id;pagar({concepto:'Matrimonio '+r.num,monto:ar.monto,pagador:r.novio.n,onok:rn=>{const x=DB.matr.find(b=>b.id==id);x.prog.recibo=rn;hist(x,'Cobró el arancel · '+rn)}})}
const docHelp=(r,c,k)=>{if(k=='bau'){const b=gp(r,`docs.${c}.bau`)||{};return (b.lib?`L. ${b.lib}, f. ${b.fol}, a. ${b.acta} · emitida ${b.emis||'—'}${venc(b.emis)?' · <b class="act">vencida (más de 6 meses)</b>':''}<br>`:'')+(ORIG[b.origen]?.[0]||'Elija abajo cómo se rellenan los datos')}if(k=='conf')return ORIG[gp(r,`docs.${c}.conf.origen`)]?.[0]||'Sin datos aún';return esc(gp(r,`docs.${c}.${k}.obs`)||'')};
